L["Set profile to |cFF00FF00%s|r."] = "Profilo impostato su |cFF00FF00%s|r."
L["Addon enabled."] = "Addon attivato."
L["Addon disabled."] = "Addon disattivato."
L["Cannot unlock UI elements in combat."] = "Non puoi sbloccare gli elementi dell'interfaccia in combattimento."
