L["No built-in default priority available for this specialization."] = "Nessuna priorità predefinita integrata disponibile per questa specializzazione."
L["Use |cFFFFD100/hekili priority name|r to change your current specialization's priority via command-line or macro."] = "Usa |cFFFFD100/hekili priority nome|r per cambiare la priorità della tua specializzazione attuale da riga di comando o con una macro."
L["\n\n|cFFFF0000You must have multiple priorities for your specialization to use this feature.|r"] = "\n\n|cFFFF0000Per usare questa funzione la tua specializzazione deve avere più priorità.|r"
