L["%s\n\nTo create a new priority, see |cFFFFD100/hekili|r > |cFFFFD100Priorities|r."] = "%s\n\nPer creare una nuova priorità, vai su |cFFFFD100/hekili|r > |cFFFFD100Priorità|r."
L["Priority set to %s%s|r."] = "Priorità impostata su %s%s|r."
L["No match found for priority '%s'.\nValid options are:"] = "Nessuna corrispondenza trovata per la priorità '%s'.\nLe opzioni valide sono:"
