L["Specialization set to |cFFFFD100%s|r."] = "Specializzazione impostata su |cFFFFD100%s|r."
L["No single specialization matches '%s'."] = "Nessuna specializzazione singola corrisponde a '%s'."
L["Use |cFFFFD100/hekili spec name|r to choose your specialization. They are:"] = "Usa |cFFFFD100/hekili spec nome|r per scegliere la tua specializzazione. Sono:"
L[" |cFF00FF00(current)|r"] = " |cFF00FF00(attuale)|r"
L[" (no priorities on Forever)"] = " (nessuna priorità su Forever)"

