L["|cFF1EFF00Import / Export|r"] = "|cFF1EFF00Importa / Esporta|r"
L["|cFFFF0000No support is offered for custom or imported priorities from elsewhere.|r\n\n|cFF00CCFFThe default priorities included within the addon are kept up to date, are compatible with your character, and do not require additional changes.|r\n\nPaste a Priority import string in the box below to begin."] = "|cFFFF0000Non viene offerto alcun supporto per priorità personalizzate o importate da altre fonti.|r\n\n|cFF00CCFFLe priorità predefinite incluse nell'addon sono tenute aggiornate, sono compatibili con il tuo personaggio e non richiedono altre modifiche.|r\n\nIncolla una stringa di importazione di una Priorità nella casella qui sotto per cominciare."
