L["Delete this Action List"] = "Elimina questa lista di azioni"
L["Delete this action list?"] = "Eliminare questa lista di azioni?"
L["Entry"] = "Voce"
L["Select the entry to modify in this action list.\n\nEntries in red are disabled, have no action set, have a conditional error, or use actions that are disabled/toggled off."] = "Scegli la voce da modificare in questa lista di azioni.\n\nLe voci in rosso sono disattivate, non hanno un'azione impostata, hanno un errore nella condizione o usano azioni disattivate/spente."
L["Unassigned"] = "Non assegnato"
L["reset |cff00ccff%s|r"] = "reimposta |cff00ccff%s|r"
L["unassigned"] = "non assegnato"
L["|cff00ccff%s|r default = |cffffd100%s|r"] = "|cff00ccff%s|r predefinito = |cffffd100%s|r"
L["set |cff00ccff%s|r = |cffffd100%s|r"] = "imposta |cff00ccff%s|r = |cffffd100%s|r"
