L["Delete this entry?"] = "Eliminare questa voce?"
L["If disabled, this entry will not be shown even if its criteria are met."] = "Se disattivata, questa voce non verrà mostrata anche se i suoi criteri sono soddisfatti."
L["Action"] = "Azione"
L["Select the action that will be recommended when this entry's criteria are met."] = "Scegli l'azione che verrà consigliata quando i criteri di questa voce sono soddisfatti."
L["Buff Name"] = "Nome del potenziamento"
L["Specify the buff to remove."] = "Indica il potenziamento da rimuovere."
L["Window Name"] = "Nome della finestra"
L["Specify the rotation window to open or close."] = "Indica la finestra di rotazione da aprire o chiudere."
L["Action Name"] = "Nome dell'azione"
L["Specify the action to cancel; the result is that the addon will allow the channel to be removed immediately."] = "Indica l'azione da annullare; il risultato è che l'addon permetterà di interrompere subito il canale."
L["Seconds"] = "Secondi"
L["Max Energy"] = "Energia massima"
-- L["When checked, this entry waits until the player has enough energy for the ability's full bonus from extra energy."] = ""
L["Caption"] = "Didascalia"
L["Captions are |cFFFF0000very|r short descriptions that can appear on the icon of a recommended ability.\n\nThis can be useful for understanding why an ability was recommended at a particular time.\n\nRequires Captions to be enabled on each display."] = "Le didascalie sono descrizioni |cFFFF0000molto|r brevi che possono comparire sull'icona di un'abilità consigliata.\n\nPossono servire a capire perché un'abilità è stata consigliata in un dato momento.\n\nRichiede che le Didascalie siano attivate su ogni riquadro."
L["Caption text should be 20 characters or less."] = "Il testo della didascalia deve essere di 20 caratteri o meno."
L["Label"] = "Etichetta"
L["Text shown on the recommendation while the Label Condition (if any) holds, e.g. a downranking note."] = "Testo mostrato sulla raccomandazione finché la Condizione dell'etichetta (se c'è) è vera, per esempio una nota sul rango ridotto."
L["Label Condition"] = "Condizione dell'etichetta"
L["If entered, the Label shows only while this is true."] = "Se compilata, l'Etichetta viene mostrata solo finché questa è vera."
L["Icon"] = "Icona"
L["A texture file ID or path to show on the recommendation in place of the ability's icon while the Icon Condition (if any) holds. A path is resolved when the list loads; a bare file ID is not checked."] = "L'ID di un file di texture o un percorso da mostrare sulla raccomandazione al posto dell'icona dell'abilità finché la Condizione dell'icona (se c'è) è vera. Un percorso viene risolto quando la lista si carica; un ID di file semplice non viene controllato."
L["Not a texture file; this line's icon is not overridden."] = "Non è un file di texture; l'icona di questa riga non viene sostituita."
L["Icon Condition"] = "Condizione dell'icona"
L["If entered, the Icon shows only while this is true."] = "Se compilata, l'Icona viene mostrata solo finché questa è vera."
L["This allows you to provide text that explains this entry, which will show when you Pause and mouseover the ability to see why this entry was recommended."] = "Qui puoi scrivere un testo che spiega questa voce, che verrà mostrato quando metti in Pausa e passi il mouse sull'abilità per vedere perché questa voce è stata consigliata."
L["Variable Name"] = "Nome della variabile"
L["Specify a name for this variable.  Variables must be lowercase with no spaces or symbols aside from the underscore."] = "Indica un nome per questa variabile.  Le variabili devono essere in minuscolo, senza spazi né simboli a parte il trattino basso."
L["Variables must be at least 3 characters in length."] = "Le variabili devono essere lunghe almeno 3 caratteri."
L["Invalid characters entered.  Try again."] = "Caratteri non validi.  Riprova."
L["Operation"] = "Operazione"
L["Add Value"] = "Aggiungi valore"
L["Ceiling of Value"] = "Arrotonda il valore per eccesso"
L["Set Default Value"] = "Imposta valore predefinito"
L["Divide Value"] = "Dividi valore"
L["Floor of Value"] = "Arrotonda il valore per difetto"
L["Maximum of Values"] = "Massimo dei valori"
L["Minimum of Values"] = "Minimo dei valori"
L["Modulo of Value"] = "Modulo del valore"
L["Multiply Value"] = "Moltiplica valore"
L["Raise Value to X Power"] = "Eleva il valore alla potenza X"
L["Reset to Default"] = "Reimposta al predefinito"
L["Set Value"] = "Imposta valore"
L["Set Value If..."] = "Imposta valore se..."
L["Subtract Value"] = "Sottrai valore"
L["Not Set"] = "Non impostato"
L["Pool for Next Entry (%s)"] = "Accumula per la voce successiva (%s)"
L["If checked, the addon will pool resources until the next entry has enough resources to use."] = "Se selezionato, l'addon accumulerà risorse finché la voce successiva avrà abbastanza risorse da usare."
L["Pooling Time"] = "Tempo di accumulo"
L["Specify the time, in seconds, as a number or as an expression that evaluates to a number.\nDefault is |cFFFFD1000.5|r.  An example expression would be |cFFFFD100energy.time_to_max|r."] = "Indica il tempo, in secondi, come numero o come espressione che dà un numero.\nIl valore predefinito è |cFFFFD1000.5|r.  Un esempio di espressione è |cFFFFD100energy.time_to_max|r."
L["Extra Pooling"] = "Accumulo extra"
L["Specify the amount of extra resources to pool in addition to what is needed for the next entry."] = "Indica la quantità di risorse extra da accumulare oltre a quelle necessarie per la voce successiva."
L["Conditions"] = "Condizioni"
L["Specify Conditions that must be met for this action to be recommended or used in generating recommendations."] = "Indica le Condizioni che devono essere soddisfatte perché questa azione venga consigliata o usata nel generare le raccomandazioni."
L["Value"] = "Valore"
L["Provide the value to store (or calculate) when this variable is invoked.\n\nIf Conditions are provided, this value is set when Conditions are met."] = "Indica il valore da memorizzare (o calcolare) quando questa variabile viene richiamata.\n\nSe sono indicate delle Condizioni, questo valore viene impostato quando le Condizioni sono soddisfatte."
L["Value when Conditions are Not Met"] = "Valore quando le Condizioni non sono soddisfatte"
L["Provide the value to store (or calculate) if Conditions are not met."] = "Indica il valore da memorizzare (o calcolare) se le Condizioni non sono soddisfatte."
L["Show Unused Modifiers (if applicable)"] = "Mostra i modificatori inutilizzati (se applicabile)"
L["If checked, additional modifiers that are not currently used by this entry."] = "Se selezionato, mostra i modificatori aggiuntivi che questa voce non usa al momento."
L["Cycle Targets"] = "Cicla i bersagli"
L["If checked, the addon will check each available target and show whether to switch targets."] = "Se selezionato, l'addon controllerà ogni bersaglio disponibile e mostrerà se conviene cambiare bersaglio."
L["Max Cycle Targets"] = "Massimo di bersagli da ciclare"
L["If cycle targets is checked, the addon will check up to the specified number of targets."] = "Se cicla i bersagli è selezionato, l'addon controllerà fino al numero di bersagli indicato."
L["Check Movement"] = "Controlla il movimento"
L["If checked, this entry can only be recommended when your character movement matches the setting."] = "Se selezionato, questa voce può essere consigliata solo quando il movimento del tuo personaggio corrisponde all'impostazione."
L["Movement"] = "Movimento"
L["If set, this entry can only be recommended when your movement matches the setting."] = "Se impostato, questa voce può essere consigliata solo quando il tuo movimento corrisponde all'impostazione."
L["Stationary"] = "Fermo"
L["Moving"] = "In movimento"
L["Use Off GCD"] = "Usa fuori dal GCD"
L["If checked, this entry can be checked even if the global cooldown (GCD) is active."] = "Se selezionato, questa voce può essere controllata anche quando il cooldown globale (GCD) è attivo."
L["Use While Casting"] = "Usa mentre lanci"
L["If checked, this entry can be checked even if you are already casting or channeling."] = "Se selezionato, questa voce può essere controllata anche se stai già lanciando o canalizzando."
L["During Channel"] = "Durante un canale"
L["If checked, this entry can only be used if you are channeling another spell."] = "Se selezionato, questa voce può essere usata solo se stai canalizzando un altro incantesimo."
L["Focus Tier"] = "Livello di focus"
L["Timeline style: 0 is off; a tier (1 highest) makes this entry a focus candidate. When it is predicted within the focus horizon it takes the Now circle; the lowest tier wins, then the soonest."] = 'Stile cronologia: 0 è disattivato; un livello (1 il più alto) rende questa voce una candidata al focus. Quando è prevista entro l\'orizzonte del focus prende il cerchio "ora"; vince il livello più basso, poi la più vicina nel tempo.'
L["Entry Cooldown"] = "Cooldown della voce"
L["If set, this entry cannot be recommended unless this time has passed since the last time the ability was used."] = "Se impostato, questa voce non può essere consigliata finché non è passato questo tempo dall'ultima volta che l'abilità è stata usata."
L["Test Conditions Immediately"] = "Verifica subito le condizioni"
L["If checked, the Conditions (above) must be met immediately for this action to be recommended or used."] = "Se selezionato, le Condizioni (sopra) devono essere soddisfatte subito perché questa azione venga consigliata o usata."
L["Additional Immediate Criteria"] = "Criteri immediati aggiuntivi"
L["If entered, these Immediate Criteria must be met before the Conditions above will be tested."] = "Se compilati, questi Criteri immediati devono essere soddisfatti prima che vengano verificate le Condizioni qui sopra."
L["List Name"] = "Nome della lista"
L["Action list names should be at least 2 characters in length."] = "I nomi delle liste di azioni devono essere lunghi almeno 2 caratteri."
L["There is already an action list by that name."] = "Esiste già una lista di azioni con questo nome."
L["Only alphanumeric characters and underscores can be used in list names."] = "Nei nomi delle liste si possono usare solo caratteri alfanumerici e trattini bassi."
L["Add List"] = "Aggiungi lista"
L["Cancel"] = "Annulla"
L["Create New Entry"] = "Crea nuova voce"
L["|cff777777<No message provided>|r"] = "|cff777777<Nessun messaggio fornito>|r"
L["|cffa0a0ffAutomatic Stress Test:|r "] = "|cffa0a0ffTest di stress automatico:|r "
L["|cffff0000WARNING:|r There are unresolved Warnings related to this priority. Please review before exporting."] = "|cffff0000ATTENZIONE:|r Ci sono Avvisi non risolti relativi a questa priorità. Controllali prima di esportare."
L["|cffffff00NOTICE:|r There are unresolved Warnings since reloading the UI. These may not be related to this priority."] = "|cffffff00NOTA:|r Ci sono Avvisi non risolti dal ricaricamento dell'interfaccia. Potrebbero non essere collegati a questa priorità."
L["|cff00ff00No warnings or errors detected!|r\n"] = "|cff00ff00Nessun avviso o errore rilevato!|r\n"
L["Stress Test Results"] = "Risultati del test di stress"
L["Toggles"] = "Interruttori"
L["Toggles are keybindings that can be used to control which abilities may be recommended and where they are displayed."] = "Gli interruttori sono scorciatoie da tastiera che servono a controllare quali abilità possono essere consigliate e dove vengono mostrate."
L["Damage Cooldowns"] = "Cooldown di danno"
L["Toggle Major and Minor Cooldowns to ensure they are recommended at ideal times."] = "Attiva o disattiva i Cooldown maggiori e minori per assicurarti che vengano consigliati nei momenti ideali."
L["Major Cooldowns"] = "Cooldown maggiori"
L["Set a key to toggle recommendations of Major Cooldowns on or off."] = "Imposta un tasto per attivare o disattivare le raccomandazioni dei Cooldown maggiori."
L["Enable Major Cooldowns"] = "Attiva i Cooldown maggiori"
L["If checked, abilities and items that require the |cFFFFD100Major Cooldowns|r toggle can be recommended.\n\nThis toggle generally applies to major damage abilities with cooldowns of 60 seconds or greater.\n\nAbilities may be added/removed from this toggle in |cFFFFD100Abilities|r and/or |cFFFFD100Gear and Items|r sections."] = "Se selezionato, possono essere consigliate le abilità e gli oggetti che richiedono l'interruttore |cFFFFD100Cooldown maggiori|r.\n\nQuesto interruttore vale in genere per le abilità di danno maggiori con cooldown di 60 secondi o più.\n\nPuoi aggiungere/togliere abilità da questo interruttore nelle sezioni |cFFFFD100Abilità|r e/o |cFFFFD100Equipaggiamento e oggetti|r."
L["Show in Separate %s Cooldowns Display"] = "Mostra nel riquadro Cooldown %s separato"
L["If checked, abilities controlled by this toggle will be shown separately in your |W%s |cFFFFD100Major Cooldowns|r|w display when the toggle is enabled.\n\nThis is an experimental feature and may not work well for some specializations."] = "Se selezionato, le abilità controllate da questo interruttore verranno mostrate separatamente nel tuo riquadro |W%s |cFFFFD100Cooldown maggiori|r|w quando l'interruttore è attivo.\n\nÈ una funzione sperimentale e potrebbe non funzionare bene per alcune specializzazioni."
L["Active During %s"] = "Attivo durante %s"
L["If checked, when any %s effect is active, the |cFFFFD100Major Cooldowns|r toggle will be treated as enabled, even if unchecked."] = "Se selezionato, quando un qualsiasi effetto %s è attivo, l'interruttore |cFFFFD100Cooldown maggiori|r verrà considerato attivo, anche se non selezionato."
L["If checked, when %s is active, the |cFFFFD100Major Cooldowns|r toggle will be treated as enabled, even if unchecked."] = "Se selezionato, quando %s è attivo, l'interruttore |cFFFFD100Cooldown maggiori|r verrà considerato attivo, anche se non selezionato."
L["Minor Cooldowns"] = "Cooldown minori"
L["Set a key to toggle recommendations of Minor Cooldowns on or off."] = "Imposta un tasto per attivare o disattivare le raccomandazioni dei Cooldown minori."
L["Enable Minor Cooldowns"] = "Attiva i Cooldown minori"
L["If checked, abilities that require the |cFFFFD100Minor Cooldowns|r toggle can be recommended.\n\nThis toggle generally applies to damage-boosting abilities with a cooldown of 30 to 60 seconds, or abilities that you may want to control separately from your major cooldowns.\n\nAbilities may be added/removed from this toggle in |cFFFFD100Abilities|r and/or |cFFFFD100Gear and Items|r sections."] = "Se selezionato, possono essere consigliate le abilità che richiedono l'interruttore |cFFFFD100Cooldown minori|r.\n\nQuesto interruttore vale in genere per le abilità che aumentano il danno con un cooldown da 30 a 60 secondi, o per le abilità che vuoi controllare separatamente dai cooldown maggiori.\n\nPuoi aggiungere/togliere abilità da questo interruttore nelle sezioni |cFFFFD100Abilità|r e/o |cFFFFD100Equipaggiamento e oggetti|r."
L["Auto-Enable when |cFFFFD100Major Cooldowns|r Active"] = "Attiva in automatico quando i |cFFFFD100Cooldown maggiori|r sono attivi"
L["If checked, when |cFFFFD100Major Cooldowns|r are enabled (or auto-enabled), your |cFFFFD100Minor Cooldowns|r may be recommended even if the toggle itself is not checked."] = "Se selezionato, quando i |cFFFFD100Cooldown maggiori|r sono attivi (o attivati in automatico), i tuoi |cFFFFD100Cooldown minori|r possono essere consigliati anche se l'interruttore stesso non è selezionato."
L["Set a key to toggle recommendations of Potions on or off."] = "Imposta un tasto per attivare o disattivare le raccomandazioni delle Pozioni."
L["Enable Potions"] = "Attiva le pozioni"
L["If checked, abilities that require the |cFFFFD100Potions|r toggle can be recommended."] = "Se selezionato, possono essere consigliate le abilità che richiedono l'interruttore |cFFFFD100Pozioni|r."
L["If checked, when |cFFFFD100Major Cooldowns|r are enabled (or auto-enabled), your |cFFFFD100Potions|r may be recommended even if the toggle itself is not checked."] = "Se selezionato, quando i |cFFFFD100Cooldown maggiori|r sono attivi (o attivati in automatico), le tue |cFFFFD100Pozioni|r possono essere consigliate anche se l'interruttore stesso non è selezionato."
L["Toggle whether priorities that move to reach the next ability show it out of range."] = "Imposta se le priorità che si muovono per raggiungere l'abilità successiva la mostrano fuori portata."
L["Set a key to toggle Movement on or off."] = "Imposta un tasto per attivare o disattivare il Movimento."
L["Enable Movement"] = "Attiva il movimento"
L["If checked, a priority that moves to reach its next ability shows that ability while you are out of range, tinted as out of range. If unchecked, the ability is hidden until you are in range."] = "Se selezionato, una priorità che si muove per raggiungere la sua abilità successiva mostra quell'abilità mentre sei fuori portata, colorata come fuori portata. Se non selezionato, l'abilità resta nascosta finché non sei a portata."
L["Interrupts and Defensives"] = "Interruzioni e difese"
L["Toggle Interrupts (and other utility) and Defensives as needed."] = "Attiva o disattiva Interruzioni (e altre utilità) e Difese secondo necessità."
L["Set a key to toggle recommendations of Interrupts (or utility abilities) on or off."] = "Imposta un tasto per attivare o disattivare le raccomandazioni delle Interruzioni (o delle abilità di utilità)."
L["Enable Interrupts"] = "Attiva le interruzioni"
L["If checked, abilities that require the |cFFFFD100Interrupts|r toggle can be recommended"] = "Se selezionato, possono essere consigliate le abilità che richiedono l'interruttore |cFFFFD100Interruzioni|r"
L["Show in Separate %s Interrupts Display"] = "Mostra nel riquadro Interruzioni %s separato"
L["If checked, abilities that require the |cFFFFD100Interrupts|r toggle will be shown separately in your %s Interrupts display."] = "Se selezionato, le abilità che richiedono l'interruttore |cFFFFD100Interruzioni|r verranno mostrate separatamente nel tuo riquadro Interruzioni %s."
L["Interrupt Timing"] = "Tempistica delle interruzioni"
L["By default, interrupts are recommended when an enemy's cast has 0.25 seconds (or less) remaining.\n\nIf set to 2, an interrupt could be recommended when the cast has less than 2 seconds remaining."] = "Per impostazione predefinita, le interruzioni vengono consigliate quando al lancio di un nemico restano 0,25 secondi (o meno).\n\nSe è impostato a 2, un'interruzione può essere consigliata quando al lancio restano meno di 2 secondi."
L["Set a key to toggle recommendations of Defensives on or off.\n\nThis toggle applies primarily to Tank specializations."] = "Imposta un tasto per attivare o disattivare le raccomandazioni delle Difese.\n\nQuesto interruttore vale soprattutto per le specializzazioni Tank."
L["Enable Defensives"] = "Attiva le difese"
L["If checked, abilities that require the |cFFFFD100Defensives|r toggle can be recommended.\n\nThis toggle applies primarily to Tank specializations."] = "Se selezionato, possono essere consigliate le abilità che richiedono l'interruttore |cFFFFD100Difese|r.\n\nQuesto interruttore vale soprattutto per le specializzazioni Tank."
L["Show in Separate %s Defensives Display"] = "Mostra nel riquadro Difese %s separato"
L["If checked, defensive/mitigation abilities will be shown separately in your |W%s |cFFFFD100Defensives|r|w display.\n\nThis toggle applies primarily to Tank specializations."] = "Se selezionato, le abilità difensive/di mitigazione verranno mostrate separatamente nel tuo riquadro |W%s |cFFFFD100Difese|r|w.\n\nQuesto interruttore vale soprattutto per le specializzazioni Tank."
L["Display Control"] = "Controllo dei riquadri"
L["Cycle through your preferred Display Modes using the keybinding you select."] = "Scorri le tue Modalità di visualizzazione preferite con la scorciatoia che scegli."
L["Display Mode"] = "Modalità di visualizzazione"
L["Pressing this binding will cycle your Display Mode through the options checked below."] = "Premendo questa scorciatoia scorrerai la Modalità di visualizzazione tra le opzioni selezionate qui sotto."
L["Select Display Mode"] = "Scegli la modalità di visualizzazione"
L["Select your Display Mode."] = "Scegli la tua Modalità di visualizzazione."
L["Automatic"] = "Automatica"
L["Single-Target"] = "Bersaglio singolo"
L["AOE (Multi-Target)"] = "AOE (più bersagli)"
L["Fixed Dual Display"] = "Doppio riquadro fisso"
L["Reactive Dual Display"] = "Doppio riquadro reattivo"
L["Select the |cFFFFD100Display Modes|r that you wish to use.  Each time you press your |cFFFFD100Display Mode|r keybinding, the addon will switch to the next checked mode."] = "Scegli le |cFFFFD100Modalità di visualizzazione|r che vuoi usare.  Ogni volta che premi la scorciatoia della |cFFFFD100Modalità di visualizzazione|r, l'addon passerà alla modalità selezionata successiva."
L["(Default)"] = "(Predefinita)"
L["If checked, the Display Mode toggle can select Automatic mode.\n\nThe Primary display shows recommendations based upon the detected number of enemies (based on your specialization's options)."] = "Se selezionato, l'interruttore Modalità di visualizzazione può scegliere la modalità Automatica.\n\nIl riquadro Principale mostra le raccomandazioni in base al numero di nemici rilevati (secondo le opzioni della tua specializzazione)."
L["%s Uses Primary Display\n%s Recommendations based on Targets Detected"] = "%s Usa il riquadro Principale\n%s Raccomandazioni in base ai bersagli rilevati"
L["If checked, the Display Mode toggle can select Single-Target mode.\n\nThe Primary display shows recommendations as though you have one target (even if more targets are detected)."] = "Se selezionato, l'interruttore Modalità di visualizzazione può scegliere la modalità Bersaglio singolo.\n\nIl riquadro Principale mostra le raccomandazioni come se avessi un solo bersaglio (anche se ne vengono rilevati di più)."
L["%s Uses Primary Display\n%s Recommendations based on 1 Target\n%s Useful when Focusing Damage on a High-Priority Enemy"] = "%s Usa il riquadro Principale\n%s Raccomandazioni in base a 1 bersaglio\n%s Utile quando concentri il danno su un nemico ad alta priorità"
L["If checked, the Display Mode toggle can select AOE mode.\n\nThe Primary display shows recommendations as though you have at least |cFFFFD100%d|r targets (even if fewer are detected).\n\nThe number of targets is set in your specialization's options."] = "Se selezionato, l'interruttore Modalità di visualizzazione può scegliere la modalità AOE.\n\nIl riquadro Principale mostra le raccomandazioni come se avessi almeno |cFFFFD100%d|r bersagli (anche se ne vengono rilevati meno).\n\nIl numero di bersagli si imposta nelle opzioni della tua specializzazione."
L["%s Uses Primary Display\n%s Recommendations based on at least |cFFFFD100%d|r Targets\n"] = "%s Usa il riquadro Principale\n%s Raccomandazioni in base ad almeno |cFFFFD100%d|r bersagli\n"
L["Dual"] = "Doppio"
L["If checked, the Display Mode toggle can select Dual mode.\n\nThe Primary display shows single-target recommendations and the AOE display shows recommendations for |cFFFFD100%d|r or more targets (even if fewer are detected).\n\nThe number of AOE targets is set in your specialization's options."] = "Se selezionato, l'interruttore Modalità di visualizzazione può scegliere la modalità Doppio.\n\nIl riquadro Principale mostra le raccomandazioni a bersaglio singolo e il riquadro AOE mostra le raccomandazioni per |cFFFFD100%d|r o più bersagli (anche se ne vengono rilevati meno).\n\nIl numero di bersagli AOE si imposta nelle opzioni della tua specializzazione."
L["%s Uses Two Displays: Primary and AOE\n%s Primary Display's Recommendations based on 1 Target\n%s AOE Display's Recommendations based on at least |cFFFFD100%d|r Targets\n%s Useful for Ranged Specializations using Damage-Based Target Detection\n"] = "%s Usa due riquadri: Principale e AOE\n%s Raccomandazioni del riquadro Principale in base a 1 bersaglio\n%s Raccomandazioni del riquadro AOE in base ad almeno |cFFFFD100%d|r bersagli\n%s Utile per le specializzazioni a distanza che usano il rilevamento dei bersagli basato sul danno\n"
L["If checked, the Display Mode toggle can select Reactive mode.\n\nThe Primary display shows single-target recommendations, while the AOE display remains hidden until/unless |cFFFFD100%d|r or more targets are detected."] = "Se selezionato, l'interruttore Modalità di visualizzazione può scegliere la modalità Reattiva.\n\nIl riquadro Principale mostra le raccomandazioni a bersaglio singolo, mentre il riquadro AOE resta nascosto finché non vengono rilevati |cFFFFD100%d|r o più bersagli."
L["%s Uses Two Displays: Primary and AOE\n%s Primary Display's Recommendations based on 1 Target\n%s AOE Display Shown when |cFFFFD100%d|r+ Targets Detected"] = "%s Usa due riquadri: Principale e AOE\n%s Raccomandazioni del riquadro Principale in base a 1 bersaglio\n%s Riquadro AOE mostrato quando vengono rilevati |cFFFFD100%d|r+ bersagli"
L["Troubleshooting"] = "Risoluzione dei problemi"
L["These keybindings help provide critical information when troubleshooting or reporting issues."] = "Queste scorciatoie servono a fornire informazioni importanti quando si risolvono problemi o si segnalano errori."
