L["Custom #1 Name"] = "Nome di Personalizzato #1"
L["Specify a descriptive name for this custom toggle."] = "Indica un nome descrittivo per questo interruttore personalizzato."
L["Custom #2"] = "Personalizzato #2"
L["Set a key to toggle your second custom set."] = "Imposta un tasto per attivare o disattivare il tuo secondo gruppo personalizzato."
L["Enable Custom #2"] = "Attiva Personalizzato #2"
L["If checked, abilities linked to Custom #2 can be recommended."] = "Se selezionato, possono essere consigliate le abilità collegate a Personalizzato #2."
